from lib import *
S = SS('h12')
steps = [
    step("客户端把 keepalive.Time 设成 200 ms,服务端用默认的 EnforcementPolicy(MinTime 5 分钟、不允许没有流时的 PING):42 秒里客户端的 PING 出现在 9.9、19.9、30.0 秒——不是 200 ms 一次,因为 grpc-go 把客户端的 Time 抬到了最小值 10 秒(读 internal/transport/http2_client.go 与 dialoptions.go 的注释);服务端对每个 PING 都回了 ACK(9.9、19.9、30.0 秒)。到 30.0 秒,服务端发来 GOAWAY:最后流 1,错误码 ENHANCE_YOUR_CALM,附加数据“too_many_pings”,连接被关。服务端的默认策略认为这个客户端 PING 太频繁(源码里 maxPingStrikes = 2)。", t=tl(S(1)), done=lidx(S(1), '30.0 秒 S→C GOAWAY'), mark=lidx(S(1), '客户端 PING 的时刻'), b=bars([['客户端 PING 个数', 3, '3'], ['服务端 GOAWAY 个数', 1, '1']], 4, mark=[0], done=[1]), kv=KV([['设置的 Time', '200 ms'], ['实际 PING 间隔', '约 10 秒(客户端下限)'], ['第 30.0 秒', 'GOAWAY ENHANCE_YOUR_CALM too_many_pings']], ['实际 PING 间隔'])),
    step("服务端把 EnforcementPolicy 放宽(MinTime 5 秒、PermitWithoutStream = true),客户端仍是 Time 10 秒、Timeout 2 秒:42 秒里 PING 在 9.9、19.9、30.0、40.0 秒,服务端的 ACK 时刻相同,GOAWAY 0 个,TCP 连接始终 1 条。客户端 keepalive 要和服务端的 EnforcementPolicy 配套:客户端的间隔不能小于服务端的 MinTime,没有在途的流还要发 PING 的话服务端要允许。", t=tl(S(2)), done=lidx(S(2), '客户端 PING 的时刻'), mark=lidx(S(2), '客户端 PING 的时刻'), b=bars([['客户端 PING 个数', 4, '4'], ['GOAWAY 个数', 0, '0'], ['TCP 连接数', 1, '1']], 5, mark=[0], done=[1, 2]), kv=KV([['服务端策略', 'MinTime 5 s + PermitWithoutStream'], ['42 秒内', '4 个 PING,4 个 ACK'], ['结果', '0 个 GOAWAY,1 条连接']], ['结果'])),
    step("连接还在、但对端变成黑洞(两个方向的数据都被代理丢弃),此时有一个挂住的调用(deadline 30 秒):开了客户端 keepalive(Time 10 s、Timeout 2 s)的,在 12.0 秒返回(黑洞之后 11.0 秒),code=Unavailable,message=“keepalive ping failed to receive ACK within timeout”;没有 keepalive 的,一直挂到 30.0 秒 deadline 到了,返回 DeadlineExceeded。TCP 本身不会告诉你对端悄悄没了(没有 FIN 也没有 RST),keepalive 是 gRPC 层发现“连接已死”的办法。", t=tl(S(3)), done=lidx(S(3), '没有 keepalive:'), mark=lidx(S(3), '有 keepalive:'), b=bars([['有 keepalive:调用返回的时刻 s', 12.0, '12.0'], ['没有 keepalive:调用返回的时刻 s', 30.0, '30.0']], 32, mark=[0], done=[1]), kv=KV([['有 keepalive', '12.0 秒 Unavailable(ACK 超时)'], ['没有 keepalive', '30.0 秒 DeadlineExceeded'], ['黑洞出现', '调用开始后 1.0 秒']], ['有 keepalive'])),
    step("服务端也可以发 keepalive:ServerParameters 的 Time 设 200 ms,实际被抬到 1 秒(服务端的下限),Timeout 1 秒。正常运行 4.5 秒,服务端的 PING 出现在 1.0、2.0、3.0、4.0 秒,客户端的 ACK 时刻相同。然后客户端到服务端的方向变成黑洞,在途的流在黑洞开始后 1.5 秒收到 Unavailable,message=“error reading from server: EOF”——按 PING 间隔和 Timeout 推算(没有单独抓这一步):黑洞开始后服务端发出的下一个 PING 等不到 ACK,等满 1 秒的 Timeout 后关闭连接,客户端看到的是连接被关闭。服务端的 keepalive 用来清理再也不会回话的客户端,不让它们的连接和流一直占着资源。", t=tl(S(4)), done=lidx(S(4), '在途的流在黑洞开始后'), mark=lidx(S(4), '正常运行 4.5 秒'), b=bars([['服务端 PING 个数(4.5 秒内)', 4, '4'], ['黑洞之后连接被关的用时 s', 1.5, '1.5']], 5, mark=[0], done=[1]), kv=KV([['设置的 Time', '200 ms,实际 1 s(服务端下限)'], ['正常时', '每 1 秒一个 PING,都有 ACK'], ['黑洞后', '1.5 秒后连接被服务端关闭']], ['黑洞后'])),
    step("PermitWithoutStream:客户端的这个选项默认是 false。同样是 Time 10 秒,连接完全空闲 25 秒,客户端发出的 PING 是 0 个;连接上有一个在途的流时 25 秒发出 2 个(9.9、19.9 秒)。所以默认情况下,空闲的连接即使被中间设备悄悄断掉,客户端也不会去探测,要到下一次调用才发现;想让空闲连接也探测,要在客户端设 PermitWithoutStream = true,并且服务端的 EnforcementPolicy 也要允许(第一节的 GOAWAY 就是不允许时的后果)。", t=tl(S(5)), done=lidx(S(5), 'PermitWithoutStream=false:'), mark=lidx(S(5), 'PermitWithoutStream=false:'), b=bars([['空闲 25 秒的 PING 个数', 0, '0'], ['有在途的流 25 秒的 PING 个数', 2, '2']], 3, mark=[0], done=[1]), kv=KV([['PermitWithoutStream=false', '空闲不发 PING'], ['有在途的流', '照常每 10 秒一个'], ['要让空闲连接也探测', '客户端 true + 服务端允许']], ['PermitWithoutStream=false'])),
]
A = mkarth('h12', 12, 'gRPC,keepalive,PING,GOAWAY,too_many_pings,EnforcementPolicy,连接探活,Go,真实验证,动画演示',
    '实测 gRPC keepalive:客户端 Time 有 10 秒下限;服务端默认策略下客户端 PING 到第三个就被 GOAWAY(too_many_pings);对端变成黑洞时有 keepalive 12 秒发现、没有的要等到 deadline;服务端也能探活;PermitWithoutStream 默认 false 时空闲连接不探测。',
    'keepalive 是 gRPC 在 HTTP/2 PING 帧上做的连接探活。它怎么设、有哪些隐藏的下限、客户端和服务端的配置不匹配会怎样、对端悄悄消失时能多快发现?这篇用本机服务端和一个能丢弃数据的代理逐项实测。',
    [('10 秒', '客户端 keepalive.Time 的下限(设成 200 ms 也会被抬到 10 秒)'), ('第 30.0 秒', '服务端默认策略下,客户端的第三个 PING 之后收到 GOAWAY too_many_pings'), ('12.0 秒 vs 30.0 秒', '对端变黑洞后,有 keepalive 与没有 keepalive 的调用返回时刻')],
    [('keepalive 是什么', '<p>用 HTTP/2 PING 帧探测连接是否还活着:隔一段时间(Time)发一个 PING,如果在 Timeout 内没有收到 ACK 就认为连接已死并关掉。客户端和服务端各自都可以发。</p>'),
     ('客户端 Time 的下限', '<p>grpc-go 里客户端 Time 小于 10 秒会被抬到 10 秒(源码),服务端的下限是 1 秒。实验里设 200 ms,客户端 PING 间隔仍是 10 秒;如果服务端用默认的 EnforcementPolicy,第三个 PING 之后就被 GOAWAY(ENHANCE_YOUR_CALM,too_many_pings)。</p>'),
     ('两端要配套', '<p>服务端的 EnforcementPolicy 决定“客户端 PING 多频繁算太频繁”(MinTime)和“没有流时能不能 PING”(PermitWithoutStream)。客户端的 keepalive 参数要和它对上,否则连接会被关。</p>'),
     ('为什么需要', '<p>对端所在机器断电、网线被拔、中间的 NAT 或防火墙悄悄丢弃连接表项时,TCP 上没有任何通知。没有 keepalive 的调用只能一直等到自己的 deadline;有 keepalive 则在 Time + Timeout 之内发现。</p>'),
     ('PermitWithoutStream', '<p>默认 false:没有在途的流时不发 PING。要让空闲连接也被探测,要设为 true,并让服务端的策略允许。</p>')],
    steps,
    [ENV_H + '。PING 与 GOAWAY 的时刻是代理在线上解析 HTTP/2 帧得到的(相对每个场景的起点);“黑洞”是代理丢弃之后的所有数据,但保持 TCP 连接;六个场景并发运行;“客户端 Time 下限 10 秒、服务端 1 秒、maxPingStrikes = 2”读自 grpc-go 源码,其余是测量',
     '没有验证:其它语言的 gRPC 实现(Java、C++ 的 keepalive 默认值与下限是否相同);真实网络里 NAT、负载均衡器的空闲超时;TCP keepalive 与 gRPC keepalive 的相互作用;第三节里 PING 具体发出的时刻(按 Time 10 秒加 Timeout 2 秒推算,与 12.0 秒吻合,但这个场景没有单独抓 PING);服务端 MaxConnectionIdle、MaxConnectionAge 等(第 40 篇)'],
    'keepalive')
